function json(data, status = 200, cache = 'no-store') {
  return new Response(JSON.stringify(data), { status, headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': cache, 'x-content-type-options': 'nosniff' } });
}
function h(v = '') { return String(v).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c])); }
function n(v) { return Number(v || 0).toLocaleString('fr-FR'); }
function fmt(v) { if (!v) return 'Unknown'; try { return new Intl.DateTimeFormat('fr-FR',{day:'2-digit',month:'2-digit',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(v)); } catch { return String(v); } }
function pct(a,b){ return b ? Math.round(Number(a||0) / Number(b||0) * 100) : 0; }
function cleanText(v, max=700){ return typeof v === 'string' ? v.replace(/[\u0000-\u001f\u007f]/g,' ').replace(/\s+/g,' ').trim().slice(0,max) : ''; }
function cleanPath(v){ if (typeof v !== 'string') return '/'; const p = v.slice(0,240).replace(/[^a-zA-Z0-9_./-]/g,''); return p.startsWith('/') ? (p.replace(/\/+$/,'') || '/') : '/'; }
function cleanKey(v){ const k = cleanText(v, 40).toLowerCase(); return /^[a-z0-9][a-z0-9_-]{1,30}$/i.test(k) ? k : ''; }
function cleanColor(v){ const c = cleanText(v,16); return /^#[0-9a-f]{6}$/i.test(c) ? c : ''; }
function arr(v){ try { const x = JSON.parse(v || '[]'); return Array.isArray(x) ? x.filter(i => typeof i === 'string') : []; } catch { return []; } }
function db(env){ return env.WIKI_DB?.prepare ? env.WIKI_DB : null; }
function isOwner(s){ return s?.role === 'owner'; }
function canAdmin(s){ return s?.role === 'owner' || s?.role === 'wiki'; }
function hourBucket(date = new Date()){ const d=new Date(date); d.setUTCMinutes(0,0,0); return d.toISOString(); }
function periodValue(v){ return PERIODS.includes(v) ? v : '30d'; }
function cutoffFor(period){ const now=Date.now(); const ms=period==='24h'?86400000:period==='7d'?7*86400000:period==='30d'?30*86400000:null; return ms ? new Date(now-ms).toISOString() : null; }
function unique(v=[]){ return [...new Set(v.filter(Boolean))]; }

async function init(env){
  const d = db(env); if (!d) return false;
  await d.exec(`
CREATE TABLE IF NOT EXISTS analytics_events (event TEXT NOT NULL,path TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',language TEXT NOT NULL DEFAULT 'en',count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event,path,detail,language));
CREATE TABLE IF NOT EXISTS analytics_hourly (event TEXT NOT NULL,path TEXT NOT NULL,detail TEXT NOT NULL DEFAULT '',language TEXT NOT NULL DEFAULT 'en',bucket TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(event,path,detail,language,bucket));
CREATE TABLE IF NOT EXISTS search_zero_terms (query TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'other',language TEXT NOT NULL DEFAULT 'en',bucket TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(query,category,language,bucket));
CREATE TABLE IF NOT EXISTS search_query_events (query TEXT NOT NULL,event TEXT NOT NULL,category TEXT NOT NULL DEFAULT 'other',language TEXT NOT NULL DEFAULT 'en',bucket TEXT NOT NULL,count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(query,event,category,language,bucket));
CREATE TABLE IF NOT EXISTS article_feedback (path TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'en',yes_count INTEGER NOT NULL DEFAULT 0,no_count INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(path,language));
CREATE TABLE IF NOT EXISTS article_feedback_comments (id INTEGER PRIMARY KEY AUTOINCREMENT,path TEXT NOT NULL,language TEXT NOT NULL DEFAULT 'en',comment TEXT NOT NULL,reason TEXT NOT NULL DEFAULT '',moderation_status TEXT NOT NULL DEFAULT 'open',hidden INTEGER NOT NULL DEFAULT 0,handled_by TEXT NOT NULL DEFAULT '',handled_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS page_meta_overrides (path TEXT PRIMARY KEY,status TEXT NOT NULL DEFAULT 'unknown',badges_json TEXT NOT NULL DEFAULT '[]',filters_json TEXT NOT NULL DEFAULT '[]',updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by TEXT NOT NULL DEFAULT 'system');
CREATE TABLE IF NOT EXISTS badge_definitions (key TEXT PRIMARY KEY,label_fr TEXT NOT NULL,label_en TEXT NOT NULL,icon TEXT NOT NULL DEFAULT '',color TEXT NOT NULL DEFAULT '',active INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_by TEXT NOT NULL DEFAULT 'system');
CREATE TABLE IF NOT EXISTS page_review_snoozes (path TEXT PRIMARY KEY,snoozed_until TEXT NOT NULL,reviewed_at TEXT NOT NULL,reviewed_by TEXT NOT NULL,baseline_no_count INTEGER NOT NULL DEFAULT 0,baseline_comment_id INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS admin_logs (id INTEGER PRIMARY KEY AUTOINCREMENT,actor TEXT NOT NULL,role TEXT NOT NULL DEFAULT 'admin',action TEXT NOT NULL,target TEXT NOT NULL DEFAULT '',payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_analytics_count ON analytics_events(count DESC);
CREATE INDEX IF NOT EXISTS idx_analytics_hourly_bucket ON analytics_hourly(bucket,event,count DESC);
CREATE INDEX IF NOT EXISTS idx_search_zero_bucket ON search_zero_terms(bucket,count DESC);
CREATE INDEX IF NOT EXISTS idx_search_query_bucket ON search_query_events(bucket,event,count DESC);
CREATE INDEX IF NOT EXISTS idx_feedback_no ON article_feedback(no_count DESC);
CREATE INDEX IF NOT EXISTS idx_feedback_comments_status ON article_feedback_comments(moderation_status, hidden);
CREATE INDEX IF NOT EXISTS idx_review_snoozes_until ON page_review_snoozes(snoozed_until);
CREATE INDEX IF NOT EXISTS idx_admin_logs_created ON admin_logs(created_at DESC);
`);
  for (const sql of [
    "ALTER TABLE article_feedback_comments ADD COLUMN reason TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE article_feedback_comments ADD COLUMN moderation_status TEXT NOT NULL DEFAULT 'open'",
    "ALTER TABLE article_feedback_comments ADD COLUMN hidden INTEGER NOT NULL DEFAULT 0",
    "ALTER TABLE article_feedback_comments ADD COLUMN handled_by TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE article_feedback_comments ADD COLUMN handled_at TEXT",
    "ALTER TABLE badge_definitions ADD COLUMN icon TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE badge_definitions ADD COLUMN color TEXT NOT NULL DEFAULT ''",
    "ALTER TABLE badge_definitions ADD COLUMN active INTEGER NOT NULL DEFAULT 1"
  ]) await d.prepare(sql).run().catch(() => null);
  return true;
}
async function log(env, s, action, target='', payload={}){ const d=db(env); if(!d) return; await init(env); await d.prepare('INSERT INTO admin_logs (actor,role,action,target,payload_json,created_at) VALUES (?,?,?,?,?,?)').bind(s?.user||'unknown', s?.role||'admin', action, target, JSON.stringify(payload), new Date().toISOString()).run().catch(()=>null); }
async function bumpAnalytics(d,event,path,detail,language,now=new Date().toISOString()){ const bucket=hourBucket(now); await Promise.all([
  d.prepare('INSERT INTO analytics_events (event,path,detail,language,count,created_at,updated_at) VALUES (?,?,?,?,1,?,?) ON CONFLICT(event,path,detail,language) DO UPDATE SET count=count+1,updated_at=excluded.updated_at').bind(event,path,detail,language,now,now).run(),
  d.prepare('INSERT INTO analytics_hourly (event,path,detail,language,bucket,count,created_at,updated_at) VALUES (?,?,?,?,?,1,?,?) ON CONFLICT(event,path,detail,language,bucket) DO UPDATE SET count=count+1,updated_at=excluded.updated_at').bind(event,path,detail,language,bucket,now,now).run()
]).catch(()=>null); }

function accounts(env){
  const raw = cleanText(env.CR_ADMIN_ACCOUNTS || '', 8000);
  if (raw) { try { const a = JSON.parse(raw); if (Array.isArray(a)) return a.filter(x => x?.user && x?.password).map(x => ({ user:String(x.user), password:String(x.password), role:x.role === 'wiki' ? 'wiki' : 'owner' })); } catch {} }
  return env.CR_ADMIN_USER && env.CR_ADMIN_PASSWORD ? [{ user: env.CR_ADMIN_USER, password: env.CR_ADMIN_PASSWORD, role: 'owner' }] : [];
}
function unauthorized(){ return new Response('Unauthorized',{status:401,headers:{'www-authenticate':'Basic realm="Cobblemon Realms Wiki Admin", charset="UTF-8"','cache-control':'no-store'}}); }
function session(env, req){
  const a = accounts(env); if (!a.length) return { denied: new Response('Wiki admin locked: credentials missing.',{status:503}) };
  const head = req.headers.get('authorization') || ''; if (!head.startsWith('Basic ')) return { denied: unauthorized() };
  let raw=''; try { raw = atob(head.slice(6)); } catch { return { denied: unauthorized() }; }
  const i = raw.indexOf(':'); const u = i >= 0 ? raw.slice(0,i) : ''; const p = i >= 0 ? raw.slice(i+1) : '';
  const found = a.find(x => x.user === u && x.password === p); if (!found) return { denied: unauthorized() };
  return { session: { user: found.user, role: found.role } };
}
function token(env){ return cleanText(env.CR_ADMIN_PATH_TOKEN || '', 300); }
function adminBase(env){ return token(env) ? `/__cr-admin/${encodeURIComponent(token(env))}` : '/__cr-admin'; }
function adminAction(env, name){ return token(env) ? `/api/admin/${encodeURIComponent(token(env))}/${name}` : `/api/admin/${name}`; }
function adminLink(env, tab, extra={}){ const q = new URLSearchParams({tab}); for (const [k,v] of Object.entries(extra)) if (v !== undefined && v !== null && v !== '') q.set(k,v); return `${adminBase(env)}?${q}`; }
function isAdminPath(url, env){ const t=token(env); return t ? (url.pathname === `/__cr-admin/${t}` || url.pathname === `/__cr-admin/${t}/`) : (url.pathname === '/__cr-admin' || url.pathname === '/__cr-admin/'); }
function isActionPath(url, env, name){ const t=token(env); return t ? url.pathname === `/api/admin/${t}/${name}` : url.pathname === `/api/admin/${name}`; }

async function assetJson(req, env, path){ const u = new URL(req.url); u.pathname=path; u.search=''; const r = await env.ASSETS.fetch(new Request(u, {method:'GET'})); if(!r.ok) return null; try { return await r.json(); } catch { return null; } }
async function baseStats(env){
  const d=db(env); if(!d) return {enabled:false,provider:'none',analytics:[],feedback:[],comments:[],overrides:[],badges:[],reviewSnoozes:[],logs:[]};
  await init(env);
  const [a,f,c,o,b,r,l] = await Promise.all([
    d.prepare('SELECT event,path,detail,language,count,updated_at AS updatedAt FROM analytics_events ORDER BY count DESC,updated_at DESC LIMIT 2400').all(),
    d.prepare('SELECT path,language,yes_count AS yes,no_count AS no,updated_at AS updatedAt FROM article_feedback ORDER BY no_count DESC,yes_count DESC LIMIT 1600').all(),
    d.prepare('SELECT id,path,language,comment,reason,moderation_status AS status,hidden,handled_by AS handledBy,handled_at AS handledAt,created_at AS createdAt FROM article_feedback_comments ORDER BY created_at DESC LIMIT 1000').all(),
    d.prepare('SELECT path,status,badges_json AS badgesJson,filters_json AS filtersJson,updated_at AS updatedAt,updated_by AS updatedBy FROM page_meta_overrides ORDER BY updated_at DESC LIMIT 1600').all(),
    d.prepare('SELECT key,label_fr AS labelFr,label_en AS labelEn,icon,color,active,updated_at AS updatedAt,updated_by AS updatedBy FROM badge_definitions ORDER BY key ASC').all(),
    d.prepare('SELECT path,snoozed_until AS snoozedUntil,reviewed_at AS reviewedAt,reviewed_by AS reviewedBy,baseline_no_count AS baselineNo,baseline_comment_id AS baselineCommentId,updated_at AS updatedAt FROM page_review_snoozes ORDER BY snoozed_until ASC').all(),
    d.prepare("SELECT id,actor,role,action,target,payload_json AS payloadJson,created_at AS createdAt FROM admin_logs WHERE action <> 'admin.view' ORDER BY created_at DESC LIMIT 400").all()
  ]);
  return { enabled:true, provider:'d1', analytics:a.results||[], feedback:f.results||[], comments:(c.results||[]).map(x=>({...x,hidden:Number(x.hidden||0)})), overrides:(o.results||[]).map(x=>({path:x.path,status:x.status,badges:arr(x.badgesJson),filters:arr(x.filtersJson),updatedAt:x.updatedAt,updatedBy:x.updatedBy})), badges:(b.results||[]).map(x=>({...x,active:Number(x.active||0)})), reviewSnoozes:(r.results||[]).map(x=>({...x,baselineNo:Number(x.baselineNo||0),baselineCommentId:Number(x.baselineCommentId||0)})), logs:l.results||[] };
}
async function periodStats(env,period){ const d=db(env); if(!d) return {periodAnalytics:[],reviewAnalytics:[],searchTerms:[],searchEvents:[]}; await init(env); const cut=cutoffFor(period), reviewCut=cutoffFor('30d'); const periodSql=cut?'WHERE bucket >= ?':''; const periodArgs=cut?[cut]:[]; const [pa,ra,sz,se]=await Promise.all([
  d.prepare(`SELECT event,path,detail,language,SUM(count) AS count,MAX(updated_at) AS updatedAt FROM analytics_hourly ${periodSql} GROUP BY event,path,detail,language ORDER BY count DESC LIMIT 3000`).bind(...periodArgs).all(),
  d.prepare('SELECT event,path,detail,language,SUM(count) AS count,MAX(updated_at) AS updatedAt FROM analytics_hourly WHERE bucket >= ? GROUP BY event,path,detail,language ORDER BY count DESC LIMIT 3000').bind(reviewCut).all(),
  d.prepare(`SELECT query,category,language,SUM(count) AS count,MAX(updated_at) AS updatedAt FROM search_zero_terms ${periodSql} GROUP BY query,category,language ORDER BY count DESC,updatedAt DESC LIMIT 500`).bind(...periodArgs).all(),
  d.prepare(`SELECT query,event,category,language,SUM(count) AS count,MAX(updated_at) AS updatedAt FROM search_query_events ${periodSql} GROUP BY query,event,category,language ORDER BY count DESC LIMIT 1200`).bind(...periodArgs).all()
 ]); return {periodAnalytics:pa.results||[],reviewAnalytics:ra.results||[],searchTerms:sz.results||[],searchEvents:se.results||[]}; }
function applyMeta(base, overrides=[], badges=[]){ const m=JSON.parse(JSON.stringify(base||{})); m.labels ||= {}; m.labels.fr ||= {}; m.labels.en ||= {}; m.labels.fr.badges ||= {}; m.labels.en.badges ||= {}; m.badgeDefinitions ||= {}; m.pages ||= {}; for(const b of badges){ if(!b.active) continue; m.labels.fr.badges[b.key]=b.labelFr||b.key; m.labels.en.badges[b.key]=b.labelEn||b.labelFr||b.key; m.badgeDefinitions[b.key]={icon:b.icon||'',color:b.color||'',source:'d1'}; } for(const o of overrides){ m.pages[o.path]={...(m.pages[o.path]||{}),status:o.status||'unknown',badges:o.badges||[],filters:o.filters||[],source:'d1',updatedAt:o.updatedAt,updatedBy:o.updatedBy}; } m.dynamicOverrides={enabled:overrides.length>0||badges.length>0,count:overrides.length,badgeCount:badges.length,source:'d1'}; return m; }
async function payload(req, env){ const period=periodValue(new URL(req.url).searchParams.get('period')||'30d'); const [build,updates,metaRaw,search,audit,st,ps] = await Promise.all([assetJson(req,env,'/build-info.json'),assetJson(req,env,'/page-updates.json'),assetJson(req,env,'/page-meta.json'),assetJson(req,env,'/search-index.json'),assetJson(req,env,'/wiki-audit.json'),baseStats(env),periodStats(env,period)]); return { buildInfo:build||{}, pageUpdates:Array.isArray(updates)?updates:[], pageMetaBase:metaRaw||{}, pageMeta:applyMeta(metaRaw||{}, st.overrides||[], st.badges||[]), pageCount:Array.isArray(search)?search.length:null, audit:audit||{counts:{critical:0,warning:0,info:0}}, stats:{...st,...ps,period}, security:{multiAccountConfigured:Boolean(env.CR_ADMIN_ACCOUNTS),d1Enabled:Boolean(db(env)),provider:db(env)?'d1':'none'} }; }
function pageMetaFor(meta, path){ const def=meta?.defaults||{status:'unknown',badges:[],filters:[]}; let out={status:def.status||'unknown',badges:def.badges||[],filters:def.filters||[]}; const p=String(path||'').replace(/\/$/,'')||'/'; const no=p.replace(/^\/fr-FR/i,''); for(const r of meta?.rules||[]){ try{ const re=new RegExp(r.match); if(re.test(p)||re.test(no)) out={...out,...r}; } catch{} } return {...out,...(meta?.pages?.[p]||meta?.pages?.[no]||{})}; }
function pageInfo(path, pages=[]){ const p=path||'/'; const page=pages.find(x=>x.path===p)||pages.find(x=>(x.path||'').replace(/\/$/,'')===(p.replace(/\/$/,'')||'/')); const lang=page?.language || (p.startsWith('/fr-FR')?'fr':'en'); return { title:page?.title || (p==='/'?'Home / Root page':p), path:p, language:lang, updatedAt:page?.updatedAt||'', exists:Boolean(page) }; }
function pageCell(path,pages=[]){ const x=pageInfo(path,pages); const missing=x.exists?'':'<br><small class="muted">Not found in current page index</small>'; return `<strong>${h(x.title)}</strong><br><code>${h(x.path)}</code><br><small>${h((x.language||'').toUpperCase())} • ${h(x.updatedAt ? 'Updated '+fmt(x.updatedAt) : 'No page update date found')}</small>${missing}`; }
function rows(items, cols, empty='No data.'){ if(!items.length) return `<div class="empty">${h(empty)}</div>`; return `<table><thead><tr>${cols.map(c=>`<th>${h(c[0])}</th>`).join('')}</tr></thead><tbody>${items.map(it=>`<tr>${cols.map(c=>`<td>${c[1](it)}</td>`).join('')}</tr>`).join('')}</tbody></table>`; }
function badge(t, kind='info'){ return `<span class="status ${kind}">${h(t)}</span>`; }
function pill(v=[]){ return v?.length ? v.map(x=>`<span class="pill">${h(x)}</span>`).join('') : '<span class="muted">None</span>'; }
function card(t,v,note=''){ return `<article class="card"><small>${h(t)}</small><strong>${h(v)}</strong><small>${h(note)}</small></article>`; }
function select(v,l,s){ return `<option value="${h(v)}"${String(v)===String(s)?' selected':''}>${h(l)}</option>`; }
function check(name,v,on){ return `<label class="check"><input type="checkbox" name="${h(name)}" value="${h(v)}"${on?' checked':''}> ${h(v)}</label>`; }
function usage(pages, meta){ const m=new Map(); for(const p of pages){ for(const b of pageMetaFor(meta,p.path).badges||[]) m.set(b,(m.get(b)||0)+1); } return m; }
function feedbackMaps(fb, comments){ const negative=new Map(), open=new Map(); for(const x of fb||[]) if(Number(x.no||0)>0) negative.set(x.path,x); for(const c of comments||[]) if(!c.hidden && (c.status||'open')==='open') open.set(c.path,(open.get(c.path)||0)+1); return {negative,open}; }
function feedbackTotals(items){ const m=new Map(); for(const x of items||[]){ const prev=m.get(x.path)||{yes:0,no:0,updatedAt:''}; prev.yes+=Number(x.yes||0); prev.no+=Number(x.no||0); if(String(x.updatedAt||'')>String(prev.updatedAt||'')) prev.updatedAt=x.updatedAt; m.set(x.path,prev); } return m; }
function activeCommentsByPath(comments){ const m=new Map(); for(const c of comments||[]){ if(c.hidden||!['open','read'].includes(c.status||'open')) continue; const list=m.get(c.path)||[]; list.push(c); m.set(c.path,list); } for(const list of m.values()) list.sort((a,b)=>Number(b.id||0)-Number(a.id||0)); return m; }
function snoozeState(snooze,no,active=[]){ const until=Date.parse(snooze?.snoozedUntil||''); const future=Boolean(snooze)&&Number.isFinite(until)&&until>Date.now(); const maxCommentId=active.reduce((max,c)=>Math.max(max,Number(c.id||0)),0); const newNegative=future&&Number(no||0)>Number(snooze?.baselineNo||0); const newComment=future&&maxCommentId>Number(snooze?.baselineCommentId||0); return {future,newNegative,newComment,interrupted:future&&(newNegative||newComment),maxCommentId}; }
function filterPages(pages, meta, fb, comments, q){ const lang=['all','fr','en'].includes(q.get('lang'))?q.get('lang'):'all'; const status=STATUSES.includes(q.get('status'))?q.get('status'):'all'; const b=cleanKey(q.get('badge')||'')||'all'; const mode=['all','negative','open'].includes(q.get('feedback'))?q.get('feedback'):'all'; const search=cleanText(q.get('q')||'',80).toLowerCase(); const maps=feedbackMaps(fb,comments); const list=pages.filter(p=>{ const m=pageMetaFor(meta,p.path); if(lang!=='all'&&p.language!==lang) return false; if(status!=='all'&&(m.status||'unknown')!==status) return false; if(b!=='all'&&!(m.badges||[]).includes(b)) return false; if(mode==='negative'&&!maps.negative.has(p.path)) return false; if(mode==='open'&&!maps.open.has(p.path)) return false; if(search&&!`${p.title||''} ${p.path||''} ${(m.badges||[]).join(' ')} ${(m.filters||[]).join(' ')}`.toLowerCase().includes(search)) return false; return true; }); return {list,filters:{lang,status,b,mode,search}}; }
function pageSlice(list,q){ const total=list.length, count=Math.max(1,Math.ceil(total/PAGE_SIZE)); const p=Math.max(1,Math.min(count,parseInt(q.get('p')||'1',10)||1)); return {total,count,page:p,visible:list.slice((p-1)*PAGE_SIZE,p*PAGE_SIZE)}; }
function pageControls(env,q,info){ if(info.count<=1) return ''; const link=p=>{const x=new URLSearchParams(q); x.set('p',p); x.set('tab','pages'); return `${adminBase(env)}?${x}`}; return `<div class="pagination"><a class="button mini" href="${h(link(1))}">First</a><a class="button mini" href="${h(link(Math.max(1,info.page-1)))}">Previous</a><span class="muted">Page ${n(info.page)} / ${n(info.count)}</span><a class="button mini" href="${h(link(Math.min(info.count,info.page+1)))}">Next</a><a class="button mini" href="${h(link(info.count))}">Last</a></div>`; }
function pageCards(pages, meta, env){ return pages.length ? pages.map(p=>{const m=pageMetaFor(meta,p.path); const kind=m.status==='verified-v6'?'ok':(m.status==='unknown'||m.status==='needs-review'||m.status==='draft'?'warn':'info'); return `<article class="page-card"><div>${pageCell(p.path,pages)}<div class="admin-actions compact"><a class="button mini" href="${h(p.path)}" target="_blank">Open</a><a class="button mini" href="${h(adminLink(env,'badges',{edit:p.path}))}">Edit badges</a><a class="button mini" href="${h(adminLink(env,'feedback',{path:p.path}))}">Feedback</a><button class="button mini" type="button" onclick="navigator.clipboard?.writeText('${h(p.path)}')">Copy path</button></div></div><div><small>Status</small>${badge(m.status||'unknown',kind)}<div>${pill(m.badges||[])}</div></div><div><small>Filters</small><div>${pill(m.filters||[])}</div><small>Updated ${h(fmt(p.updatedAt))}</small></div></article>`}).join('') : '<div class="empty">No pages match these filters.</div>'; }
function feedbackReasonLabel(reason){ return ({outdated:'Outdated',incorrect:'Incorrect',missing:'Missing info',unclear:'Unclear','broken-link':'Broken link',other:'Other'})[reason]||'Not specified'; }
function feedbackTable(items, comments, env, pages){ const latest=new Map(); for(const c of comments||[]) if(!c.hidden&&!latest.has(c.path)) latest.set(c.path,c); return rows(items.slice(0,180), [['Page',i=>pageCell(i.path,pages)], ['Votes',i=>`<strong>${n(i.yes)}</strong> yes<br><strong>${n(i.no)}</strong> no`], ['Score',i=>`${pct(i.yes,Number(i.yes||0)+Number(i.no||0))}%<br><small>${n(Number(i.yes||0)+Number(i.no||0))} total votes</small>`], ['Latest active feedback',i=>latest.get(i.path)?`${badge(feedbackReasonLabel(latest.get(i.path).reason),latest.get(i.path).reason?'warn':'info')}<br>${h(latest.get(i.path).comment||'No comment')}<br><small>${h(fmt(latest.get(i.path).createdAt))}</small>`:'<span class="muted">No active written feedback</span>'], ['Actions',i=>`<div class="admin-actions compact"><a class="button mini" href="${h(i.path)}" target="_blank">Open page</a><a class="button mini" href="${h(adminLink(env,'badges',{edit:i.path}))}">Edit badges</a><a class="button mini" href="${h(adminLink(env,'feedback',{path:i.path}))}">Comments</a><button class="button mini" type="button" onclick="navigator.clipboard?.writeText('${h(i.path)}')">Copy path</button></div>`]], 'No feedback stored yet.'); }
function commentsTable(items, env, s, archived, pages){ return rows(items.slice(0,260), [['Page',i=>pageCell(i.path,pages)], ['Reason',i=>badge(feedbackReasonLabel(i.reason),i.reason?'warn':'info')], ['Comment',i=>h(i.comment||'No written comment')], ['Status',i=>badge(i.hidden?'archived':i.status||'open', i.hidden?'info':i.status==='resolved'?'ok':i.status==='open'?'warn':'info')], ['Handled',i=>`${h(i.handledBy||'')}<br><small>${h(fmt(i.handledAt))}</small>`], ['Moderation',i=>{const del=isOwner(s)?`<button class="button mini danger" name="action" value="delete">Delete permanently</button>`:''; const buttons=archived?`<button class="button mini" name="status" value="read">Restore</button>`:`<button class="button mini" name="status" value="read">Read</button><button class="button mini" name="status" value="resolved">Resolved</button><button class="button mini" name="status" value="archived">Archive</button>`; return `<form method="post" action="${h(adminAction(env,'feedback'))}" class="inline-form"><input type="hidden" name="id" value="${h(i.id)}">${buttons}${del}<a class="button mini" href="${h(i.path)}" target="_blank">Open</a></form>`;}]], archived?'No archived feedback comments.':'No active written feedback comments.'); }
function eventTotal(a,event){ return (a||[]).filter(x=>x.event===event).reduce((s,x)=>s+Number(x.count||0),0); }
function aggregateBy(items,keyFn){ const m=new Map(); for(const x of items||[]){ const k=keyFn(x); const prev=m.get(k)||{count:0,updatedAt:''}; prev.count+=Number(x.count||0); if(String(x.updatedAt||'')>String(prev.updatedAt||'')) prev.updatedAt=x.updatedAt; m.set(k,prev); } return m; }
function topPagesTable(analytics,pages){ const m=aggregateBy((analytics||[]).filter(x=>x.event==='pageview'),x=>x.path); const items=[...m.entries()].map(([path,v])=>({path,...v})).sort((a,b)=>b.count-a.count).slice(0,30); return rows(items,[['Page',i=>pageCell(i.path,pages)],['Views',i=>`<strong>${n(i.count)}</strong>`],['Last activity',i=>h(fmt(i.updatedAt))]],'No page views in this period.'); }
function zeroSearchTable(items){ return rows((items||[]).slice(0,80),[['Search',i=>`<strong>${h(i.query)}</strong><br><small>${h((i.language||'').toUpperCase())}</small>`],['Category',i=>badge(i.category||'other')],['Count',i=>`<strong>${n(i.count)}</strong>`],['Last seen',i=>h(fmt(i.updatedAt))]],'No exact zero-result search terms collected in this period.'); }
function searchConversionTable(events){ const m=new Map(); for(const x of events||[]){ const key=`${x.language}|${x.category}|${x.query}`; const row=m.get(key)||{query:x.query,language:x.language,category:x.category,searches:0,clicks:0,zeros:0,updatedAt:''}; if(x.event==='search')row.searches+=Number(x.count||0); if(x.event==='click')row.clicks+=Number(x.count||0); if(x.event==='zero')row.zeros+=Number(x.count||0); if(String(x.updatedAt||'')>row.updatedAt)row.updatedAt=x.updatedAt||''; m.set(key,row); } const items=[...m.values()].filter(x=>x.searches||x.clicks).sort((a,b)=>b.searches-a.searches||b.clicks-a.clicks).slice(0,80); return rows(items,[['Query',i=>`<strong>${h(i.query)}</strong><br><small>${h((i.language||'').toUpperCase())} • ${h(i.category||'other')}</small>`],['Stable searches',i=>n(i.searches)],['Result clicks',i=>n(i.clicks)],['Conversion',i=>`${Math.min(100,pct(i.clicks,i.searches))}%`],['Last seen',i=>h(fmt(i.updatedAt))]],'No successful search conversion data in this period yet.'); }
function notFoundTable(analytics,pages){ const m=aggregateBy((analytics||[]).filter(x=>x.event==='not_found'),x=>`${x.path}|${x.language}`); const items=[...m.entries()].map(([key,v])=>{const [path,language]=key.split('|'); return {path,language,...v};}).sort((a,b)=>b.count-a.count).slice(0,60); return rows(items,[['Requested path',i=>`${pageCell(i.path,pages)}<br><small>${h(i.language.toUpperCase())}</small>`],['Hits',i=>`<strong>${n(i.count)}</strong>`],['Last seen',i=>h(fmt(i.updatedAt))]],'No 404 events in this period.'); }
function outboundTable(analytics,pages){ const m=new Map(); for(const x of (analytics||[]).filter(x=>x.event==='outbound')){const key=`${x.detail||'external'}|${x.path}`; const prev=m.get(key)||{destination:x.detail||'external',path:x.path,count:0,updatedAt:''}; prev.count+=Number(x.count||0); if(String(x.updatedAt||'')>String(prev.updatedAt||''))prev.updatedAt=x.updatedAt; m.set(key,prev);} const items=[...m.values()].sort((a,b)=>b.count-a.count).slice(0,60); return rows(items,[['Destination',i=>badge(i.destination)],['Source page',i=>pageCell(i.path,pages)],['Clicks',i=>`<strong>${n(i.count)}</strong>`],['Last activity',i=>h(fmt(i.updatedAt))]],'No outbound clicks in this period.'); }
function negativeFeedbackTable(periodAnalytics,feedback,comments,pages,period){ const periodMap=aggregateBy((periodAnalytics||[]).filter(x=>x.event==='feedback_no'),x=>x.path); const openMap=new Map(); for(const c of comments||[]) if(!c.hidden&&['open','read'].includes(c.status||'open')) openMap.set(c.path,(openMap.get(c.path)||0)+1); const lifetime=feedbackTotals(feedback); const paths=new Set(period==='all'?[...lifetime.keys()]:[...periodMap.keys()]); const items=[...paths].map(path=>{const f=lifetime.get(path)||{}; const p=periodMap.get(path)||{}; return {path,periodNo:period==='all'?Number(f.no||0):Number(p.count||0),yes:Number(f.yes||0),no:Number(f.no||0),open:openMap.get(path)||0,updatedAt:p.updatedAt||f.updatedAt||''};}).filter(x=>x.periodNo>0).sort((a,b)=>b.periodNo-a.periodNo||b.open-a.open).slice(0,60); return rows(items,[['Page',i=>pageCell(i.path,pages)],['Negative in period',i=>`<strong>${n(i.periodNo)}</strong>`],['Lifetime quality',i=>`${pct(i.yes,i.yes+i.no)}% helpful<br><small>${n(i.yes+i.no)} votes</small>`],['Open items',i=>i.open?badge(`${n(i.open)} active`,'warn'):badge('Clear','ok')],['Last activity',i=>h(fmt(i.updatedAt))]],'No negative feedback in this period.'); }
function languageTable(analytics){ const m=aggregateBy((analytics||[]).filter(x=>x.event==='pageview'),x=>x.language||'en'); const items=[...m.entries()].map(([language,v])=>({language,...v})).sort((a,b)=>b.count-a.count); const total=items.reduce((s,x)=>s+x.count,0); return rows(items,[['Language',i=>badge((i.language||'').toUpperCase())],['Views',i=>n(i.count)],['Share',i=>`${pct(i.count,total)}%`]],'No language traffic data in this period.'); }
function statusTrafficTable(analytics,pages,meta){ const m=new Map(); const views=aggregateBy((analytics||[]).filter(x=>x.event==='pageview'),x=>x.path); for(const [path,v] of views){ const status=pageMetaFor(meta,path).status||'unknown'; m.set(status,(m.get(status)||0)+v.count); } const total=[...m.values()].reduce((s,x)=>s+x,0); const items=[...m.entries()].map(([status,count])=>({status,count})).sort((a,b)=>b.count-a.count); return rows(items,[['Status',i=>badge(i.status,i.status==='verified-v6'?'ok':i.status==='legacy-5'?'info':'warn')],['Views',i=>n(i.count)],['Share',i=>`${pct(i.count,total)}%`]],'No status exposure data in this period.'); }
function periodToolbar(env,period){ return `<div class="toolbar period-toolbar"><span class="muted">Period</span>${[['24h','24 hours'],['7d','7 days'],['30d','30 days'],['all','All time']].map(([v,l])=>`<a class="button mini ${period===v?'is-current':''}" href="${h(adminLink(env,'stats',{period:v}))}">${h(l)}</a>`).join('')}</div>`; }
function statsPanel(env,st,pages,meta,feedback,comments){ const period=st.period||'30d'; const analytics=period==='all'?st.analytics||[]:st.periodAnalytics||[]; const label=period==='24h'?'last 24 hours':period==='7d'?'last 7 days':period==='30d'?'last 30 days':'all time'; const pageviews=eventTotal(analytics,'pageview'), zeros=eventTotal(analytics,'search_zero'), nf=eventTotal(analytics,'not_found'), outbound=eventTotal(analytics,'outbound'); const lifetimeNo=[...feedbackTotals(feedback).values()].reduce((s,x)=>s+Number(x.no||0),0); const negative=period==='all'?lifetimeNo:eventTotal(analytics,'feedback_no'); return `${periodToolbar(env,period)}<div class="hero-grid">${card('Pageviews',pageviews,label)}${card('Zero-result searches',zeros,label)}${card('404 hits',nf,label)}${card('Negative feedback',negative,label)}</div><div class="hero-grid">${card('Outbound clicks',outbound,label)}${card('Exact zero terms',(st.searchTerms||[]).length,'unique queries')}${card('Tracked pages',new Set((analytics||[]).filter(x=>x.event==='pageview').map(x=>x.path)).size,'with traffic')}${card('Search telemetry',(st.searchEvents||[]).length,'aggregated rows')}</div><p class="data-note">Search conversion uses a stable query after 900 ms, not each keystroke. This means users do not need to press Enter for a search to count.</p><section class="section"><div class="section-head"><h2>🔥 Most viewed pages</h2>${badge(label)}</div>${topPagesTable(analytics,pages)}</section><section class="section"><div class="section-head"><h2>🎯 Search conversion</h2>${badge(label)}</div>${searchConversionTable(st.searchEvents||[])}</section><section class="section"><div class="section-head"><h2>🔎 Searches with no result</h2>${badge(`${n((st.searchTerms||[]).length)} exact terms`,(st.searchTerms||[]).length?'warn':'ok')}</div>${zeroSearchTable(st.searchTerms||[])}</section><section class="section"><div class="section-head"><h2>🚧 Frequent 404s</h2>${badge(`${n(nf)} hits`,nf?'warn':'ok')}</div>${notFoundTable(analytics,pages)}</section><section class="section"><div class="section-head"><h2>↗ External link clicks</h2>${badge(`${n(outbound)} clicks`)}</div>${outboundTable(analytics,pages)}</section><section class="section"><div class="section-head"><h2>👎 Negative feedback</h2>${badge(`${n(negative)} votes`,negative?'warn':'ok')}</div>${negativeFeedbackTable(analytics,feedback,comments,pages,period)}</section><div class="grid-2"><section class="section"><h2>🌐 Traffic by language</h2>${languageTable(analytics)}</section><section class="section"><h2>🏷️ Traffic by page status</h2>${statusTrafficTable(analytics,pages,meta)}</section></div>`; }
function reviewQueue(pages, meta, fb, comments, analytics, snoozes=[]){ const feedbackByPath=feedbackTotals(fb); const commentsByPath=activeCommentsByPath(comments); const snoozeByPath=new Map((snoozes||[]).map(x=>[x.path,x])); const views=aggregateBy((analytics||[]).filter(x=>x.event==='pageview'),x=>x.path); const maxViews=Math.max(1,...[...views.values()].map(x=>x.count)); const out=[]; for(const p of pages||[]){ if(!p.path||p.path==='/') continue; const m=pageMetaFor(meta,p.path); const f=feedbackByPath.get(p.path)||{yes:0,no:0}; const active=commentsByPath.get(p.path)||[]; const viewCount=Number(views.get(p.path)?.count||0); const yes=Number(f.yes||0), no=Number(f.no||0), total=yes+no; const snooze=snoozeByPath.get(p.path); const snoozeInfo=snoozeState(snooze,no,active); if(snoozeInfo.future&&!snoozeInfo.interrupted) continue; let score=0; const signals=[]; let actionable=false; if(snoozeInfo.interrupted){score+=20;signals.push('new feedback since last review');actionable=true;} else if(snooze&&Date.parse(snooze.snoozedUntil||'')<=Date.now()){score+=8;signals.push('scheduled review due');actionable=true;} if(active.length){ const points=Math.min(45,active.length*25); score+=points; signals.push(`${active.length} active feedback item${active.length>1?'s':''}`); actionable=true; } if(no>0){ score+=Math.min(30,no*3); signals.push(`${no} negative vote${no>1?'s':''}`); actionable=true; } if(total>=3&&no/total>=.25){ const ratio=Math.round(no/total*100); score+=Math.min(25,Math.round(no/total*25)); signals.push(`${ratio}% negative ratio`); } if(m.status==='needs-review'){score+=35;signals.push('needs-review status');actionable=true;} else if(m.status==='unknown'){score+=30;signals.push('unknown status');actionable=true;} else if(m.status==='draft'){score+=25;signals.push('draft status');actionable=true;} else if(m.status==='legacy-5'){score+=15;signals.push('legacy 5.x');actionable=true;} const age=p.updatedAt?Math.floor((Date.now()-new Date(p.updatedAt).getTime())/86400000):0; if(age>365){score+=15;signals.push(`stale ${age}d`);actionable=true;} else if(age>180){score+=8;signals.push(`aging ${age}d`);} if(!m.badges?.length){score+=10;signals.push('no badge');actionable=true;} if(!m.filters?.length){score+=8;signals.push('no filter');actionable=true;} if(actionable&&viewCount>0){const traffic=Math.min(20,Math.round(viewCount/maxViews*20)); score+=traffic; if(traffic>=5)signals.push(`${viewCount} views / 30d`);} if(!actionable||score<15)continue; score=Math.min(100,score); const severity=score>=80?'Critical':score>=60?'High':score>=35?'Medium':'Low'; const latest=active[0]; out.push({path:p.path,title:p.title||p.path,priority:score,severity,signals,detail:latest?`${feedbackReasonLabel(latest.reason)}${latest.comment?`: ${latest.comment}`:''}`:'',views:viewCount,yes,no,open:active.length,status:m.status||'unknown',snoozeInterrupted:snoozeInfo.interrupted}); } return out.sort((a,b)=>b.priority-a.priority||b.views-a.views||a.path.localeCompare(b.path)); }
function currentSnoozes(snoozes,fb,comments,pages){ const feedbackByPath=feedbackTotals(fb); const commentsByPath=activeCommentsByPath(comments); return (snoozes||[]).map(x=>{const f=feedbackByPath.get(x.path)||{no:0}; const active=commentsByPath.get(x.path)||[]; return {...x,...snoozeState(x,Number(f.no||0),active),page:pageInfo(x.path,pages)};}).filter(x=>x.future&&!x.interrupted).sort((a,b)=>String(a.snoozedUntil).localeCompare(String(b.snoozedUntil))); }
function reviewedRecently(snoozes,pages){ const cutoff=Date.now()-90*86400000; return (snoozes||[]).filter(x=>Date.parse(x.reviewedAt||'')>=cutoff).map(x=>({...x,page:pageInfo(x.path,pages)})).sort((a,b)=>String(b.reviewedAt).localeCompare(String(a.reviewedAt))).slice(0,250); }
function reviewActionForm(path,env){ return `<form method="post" action="${h(adminAction(env,'review'))}" class="inline-form review-actions"><input type="hidden" name="path" value="${h(path)}"><button class="button mini" name="days" value="30">OK 30d</button><button class="button mini success" name="days" value="60">✓ OK 60d</button><button class="button mini" name="days" value="90">OK 90d</button></form>`; }
function reviewTable(q, env){ return rows(q.slice(0,180), [['Priority',i=>`${badge(`${i.severity} ${n(i.priority)}`,i.severity==='Critical'?'danger':i.severity==='High'||i.severity==='Medium'?'warn':'info')}${i.snoozeInterrupted?`<br>${badge('Reopened early','warn')}`:''}`],['Page',i=>`${h(i.title)}<br><code>${h(i.path)}</code><br><small>${h(i.status)}</small>`],['Signals',i=>`${i.signals.map(x=>`<span class="signal">${h(x)}</span>`).join('')} ${i.detail?`<br><small>${h(i.detail)}</small>`:''}`],['Audience / feedback',i=>`<strong>${n(i.views)}</strong> views / 30d<br><small>${n(i.yes)} yes • ${n(i.no)} no • ${n(i.open)} active</small>`],['Actions',i=>`<div class="admin-actions compact"><a class="button mini" href="${h(i.path)}" target="_blank">Open</a><a class="button mini" href="${h(adminLink(env,'badges',{edit:i.path}))}">Edit metadata</a><a class="button mini" href="${h(adminLink(env,'feedback',{path:i.path}))}">Feedback</a>${reviewActionForm(i.path,env)}</div>`]], 'No page currently needs attention.'); }
function bulkReviewTable(q,env){ if(!q.length)return '<div class="empty">No page currently needs attention.</div>'; return `<form method="post" action="${h(adminAction(env,'review'))}" class="bulk-review"><input type="hidden" name="action" value="bulk-preview"><div class="toolbar"><strong>Bulk review</strong><span class="muted">Select checked pages, preview, then confirm.</span><select name="days"><option value="30">OK for 30 days</option><option value="60" selected>OK for 60 days</option><option value="90">OK for 90 days</option></select><button class="button primary" type="submit">Preview selected</button></div><table><thead><tr><th>Select</th><th>Priority</th><th>Page</th><th>Signals</th><th>Open</th></tr></thead><tbody>${q.slice(0,180).map(i=>`<tr><td><input type="checkbox" name="path" value="${h(i.path)}" aria-label="Select ${h(i.title)}"></td><td>${badge(`${i.severity} ${n(i.priority)}`,i.severity==='Critical'?'danger':i.severity==='High'||i.severity==='Medium'?'warn':'info')}</td><td><strong>${h(i.title)}</strong><br><code>${h(i.path)}</code></td><td>${i.signals.map(x=>`<span class="signal">${h(x)}</span>`).join('')}</td><td><div class="admin-actions compact"><a class="button mini" href="${h(i.path)}" target="_blank">Page</a><a class="button mini" href="${h(adminLink(env,'badges',{edit:i.path}))}">Metadata</a></div></td></tr>`).join('')}</tbody></table></form>`; }
function snoozedReviewTable(items,env){ return rows(items.slice(0,220),[['Page',i=>`${h(i.page.title)}<br><code>${h(i.path)}</code><br><small>${h((i.page.language||'').toUpperCase())}</small>`],['Next review',i=>`${badge(fmt(i.snoozedUntil),'ok')}<br><small>Reviewed ${h(fmt(i.reviewedAt))}</small>`],['Reviewed by',i=>h(i.reviewedBy||'Unknown')],['Action',i=>`<form method="post" action="${h(adminAction(env,'review'))}" class="inline-form"><input type="hidden" name="path" value="${h(i.path)}"><input type="hidden" name="action" value="cancel"><button class="button mini">Review now</button><a class="button mini" href="${h(i.path)}" target="_blank">Open page</a></form>`]],'No page is currently marked OK for later review.'); }
function recentReviewTable(items,env){ return rows(items,[['Page',i=>`${h(i.page.title)}<br><code>${h(i.path)}</code>`],['Reviewed',i=>h(fmt(i.reviewedAt))],['By',i=>h(i.reviewedBy||'Unknown')],['Next review',i=>h(fmt(i.snoozedUntil))],['Action',i=>`<a class="button mini" href="${h(i.path)}" target="_blank">Open page</a>`]],'No review acknowledgement in the last 90 days.'); }
function reviewCalendar(items){ const now=Date.now(), d7=now+7*86400000, d30=now+30*86400000; const next7=items.filter(x=>Date.parse(x.snoozedUntil)<=d7).length, next30=items.filter(x=>Date.parse(x.snoozedUntil)<=d30).length; return `<div class="hero-grid">${card('Next 7 days',next7,'scheduled reviews')}${card('Next 30 days',next30,'scheduled reviews')}${card('Later',Math.max(0,items.length-next30),'after 30 days')}${card('Scheduled total',items.length,'OK for now')}</div>`; }
function subnav(env,tab,key,current,items){ return `<nav class="subnav">${items.map(([value,label])=>`<a class="${current===value?'is-active':''}" href="${h(adminLink(env,tab,{[key]:value}))}">${h(label)}</a>`).join('')}</nav>`; }
function auditSeverity(item){ return item?.severity==='critical'?'danger':item?.severity==='warning'?'warn':'info'; }
function auditLinks(audit,pages){ const broken=audit?.links?.broken||[], orphans=audit?.links?.orphanPages||[], malformed=audit?.links?.malformedExternal||[]; return `<div class="hero-grid">${card('Broken destinations',broken.length,'internal links')}${card('Orphan pages',orphans.length,'no inbound link')}${card('Malformed external',malformed.length,'invalid URL syntax')}${card('Missing images',(audit?.images?.missing||[]).length,'local assets')}</div><section class="section"><h2>Broken internal destinations</h2>${rows(broken,[['Destination',i=>`<code>${h(i.destination)}</code>`],['References',i=>n(i.hits)],['Referenced by',i=>i.sources.map(s=>`<a class="text-link" href="${h(s)}" target="_blank">${h(pageInfo(s,pages).title)}</a><br><small><code>${h(s)}</code></small>`).join('<br>')]],'No broken internal links detected at build time.')}</section><section class="section"><h2>Orphan pages</h2>${rows(orphans,[['Page',i=>pageCell(i.path,pages)],['Severity',i=>badge(i.severity||'warning',auditSeverity(i))]],'No orphan pages detected.')}</section>`; }
function auditTranslations(audit,pages){ const t=audit?.translations||{}; return `<div class="hero-grid">${card('English pages',t.englishPages||0,'source language set')}${card('French pages',t.frenchPages||0,'translated pages')}${card('Coverage',`${t.coveragePercent??100}%`,'EN pages with FR pair')}${card('Missing pairs',(t.missingFr||[]).length+(t.missingEn||[]).length,'to inspect')}</div><div class="grid-2"><section class="section"><h2>Missing French page</h2>${rows(t.missingFr||[],[['English page',i=>pageCell(i.path,pages)],['Expected FR path',i=>`<code>${h(i.expected)}</code>`]],'No missing French pair.')}</section><section class="section"><h2>Missing English page</h2>${rows(t.missingEn||[],[['French page',i=>pageCell(i.path,pages)],['Expected EN path',i=>`<code>${h(i.expected)}</code>`]],'No missing English pair.')}</section></div>`; }
function auditContent(audit,pages){ const warnings=audit?.content?.warnings||[]; const labels={'very-short':'Very short page','no-sections':'No H2 sections','no-internal-link':'No internal links','missing-description':'Missing description'}; return `<section class="section"><div class="section-head"><h2>Content completeness warnings</h2>${badge(`${n(warnings.length)} informational`,'info')}</div><p class="data-note">These are editorial hints only. They do not mean that the page is wrong.</p>${rows(warnings,[['Page',i=>pageCell(i.path,pages)],['Check',i=>badge(labels[i.type]||i.type,'info')],['Value',i=>i.value!==undefined?n(i.value):'<span class="muted">Check manually</span>'],['Action',i=>`<a class="button mini" href="${h(i.path)}" target="_blank">Open</a>`]],'No content completeness warnings.')}</section>`; }
function auditSources(audit){ const s=audit?.sources||{}, meta=audit?.metadata?.issues||[], images=audit?.images?.missing||[]; return `<div class="grid-2"><section class="section"><h2>Generated pages without source</h2>${rows(s.generatedWithoutSource||[],[['Path',i=>`<code>${h(i.path)}</code>`],['Expected source',i=>`<code>${h(i.source)}</code>`]],'Every generated page has a source Markdown file.')}</section><section class="section"><h2>Markdown without generated page</h2>${rows(s.markdownWithoutPage||[],[['Source',i=>`<code>${h(i.source)}</code>`],['Level',i=>badge('Info','info')]],'No unpaired Markdown source detected.')}</section></div><section class="section"><h2>Metadata integrity</h2>${rows(meta,[['Type',i=>badge(i.type,auditSeverity(i))],['Value',i=>`<code>${h(i.value||'')}</code>`],['Rule',i=>i.rule===undefined?'Default':n(i.rule)]],'No metadata integrity issue.')}</section><section class="section"><h2>Missing local images</h2>${rows(images,[['Source page',i=>`<code>${h(i.source)}</code>`],['Image',i=>`<code>${h(i.image)}</code>`]],'No missing local image detected.')}</section>`; }
function auditOverview(audit){ const c=audit?.counts||{}; return `<div class="hero-grid">${card('Critical',c.critical||0,'must inspect')}${card('Warnings',c.warning||0,'maintenance')}${card('Info',c.info||0,'editorial hints')}${card('Generated',fmt(audit?.generatedAt),'audit timestamp')}</div><p class="data-note">Audit V2 is generated during the site build. It checks internal links, orphan pages, translation pairs, source mapping, local images, metadata integrity and lightweight content completeness.</p>`; }
function wikiHealth(audit,queue,comments){ const c=audit?.counts||{}, critical=queue.filter(x=>x.severity==='Critical').length, high=queue.filter(x=>x.severity==='High').length, open=(comments||[]).filter(x=>!x.hidden&&['open','read'].includes(x.status||'open')).length; const deductions=Math.min(36,Number(c.critical||0)*6)+Math.min(22,Number(c.warning||0))+Math.min(24,critical*5+high*2)+Math.min(12,open); const score=Math.max(0,100-deductions); const label=score>=90?'Excellent':score>=75?'Good':score>=55?'Needs attention':'Degraded'; return {score,label,critical,high,open}; }
function logTheme(action=''){ if(action.startsWith('badge_definition')||action.startsWith('page_meta'))return 'badges'; if(action.startsWith('page_review'))return 'reviews'; if(action.startsWith('feedback'))return 'feedback'; return 'system'; }
function logLabel(action=''){ const map={'page_meta.update':'Page metadata updated','badge_definition.upsert':'Badge definition updated','page_review.ok_for_now':'Page review acknowledged','page_review.review_now':'Review rescheduled now','page_review.bulk_ok_for_now':'Bulk review acknowledged','feedback.moderate':'Feedback moderated','feedback.delete':'Feedback permanently deleted','feedback.purge_archived':'Feedback archive purged'}; return map[action]||action.replace(/[._]/g,' '); }
function logSummary(item){ let p={}; try{p=JSON.parse(item.payloadJson||'{}')}catch{} const parts=[]; if(p.status)parts.push(`status ${p.status}`); if(Array.isArray(p.badges))parts.push(`${p.badges.length} badges`); if(p.days)parts.push(`${p.days}d`); if(p.deleted!==undefined)parts.push(`${p.deleted} deleted`); if(p.count!==undefined)parts.push(`${p.count} pages`); return parts.join(' • '); }
function logsPanel(logs,env,current){ const clean=(logs||[]).filter(x=>x.action!=='admin.view'); const filtered=current==='global'?clean:clean.filter(x=>logTheme(x.action)===current); const nav=subnav(env,'logs','logView',current,[['global','Global'],['badges','Badges & Metadata'],['reviews','Reviews'],['feedback','Feedback'],['system','System']]); return `${nav}<div class="log-list">${filtered.length?filtered.slice(0,180).map(i=>`<article class="log-card"><div><span class="log-icon">${logTheme(i.action)==='badges'?'🏷️':logTheme(i.action)==='reviews'?'✅':logTheme(i.action)==='feedback'?'💬':'⚙️'}</span><div><strong>${h(logLabel(i.action))}</strong><small>${h(i.actor)} • ${h(i.role)} • ${h(fmt(i.createdAt))}</small></div></div><div><code>${h(i.target||'')}</code>${logSummary(i)?`<small>${h(logSummary(i))}</small>`:''}</div></article>`).join(''):'<div class="empty">No log in this category.</div>'}</div>`; }
function adminNav(env, active, s){ const groups=[['Dashboard',[['overview','🏠 Overview']]],['Content',[['pages','📄 Pages'],['to-review','✅ To Review']]],['Insights',[['stats','📊 Stats'],['feedback','👍 Feedback'],['audit','🧪 Audit']]],['Configuration',[['badges','🏷️ Badges']]],['System',[['logs','📜 Logs'],['maintenance','⚙️ Maintenance']]]]; if(isOwner(s))groups[4][1].push(['security','🔐 Security']); return groups.map(([label,tabs])=>`<div class="nav-group"><small>${h(label)}</small>${tabs.map(([t,l])=>`<a class="${t===active?'is-active':''}" href="${h(adminLink(env,t))}">${h(l)}</a>`).join('')}</div>`).join(''); }

async function formData(req){ const f=await req.formData(); const p={}; for(const [k,v] of f.entries()){ if(p[k]){ if(!Array.isArray(p[k])) p[k]=[p[k]]; p[k].push(v); } else p[k]=v; } return p; }
async function saveMeta(req, env){ const auth=session(env,req); if(auth.denied) return auth.denied; const s=auth.session; if(!canAdmin(s)||!db(env)) return json({error:'Forbidden'},403); const p=await formData(req); const path=cleanPath(p.path); if(path==='/') return json({error:'Concrete page path required'},400); const st=await baseStats(env); const raw=await assetJson(req,env,'/page-meta.json')||{}; const allowed=new Set([...Object.keys(raw.labels?.fr?.badges||raw.labels?.en?.badges||{}),...(st.badges||[]).filter(x=>x.active).map(x=>x.key)]); const badges=[].concat(p.badges||[]).filter(x=>allowed.has(x)); const filters=[].concat(p.filters||[]).filter(x=>FILTERS.includes(x)); const status=STATUSES.includes(p.status)?p.status:'unknown'; const now=new Date().toISOString(); await init(env); await db(env).prepare('INSERT INTO page_meta_overrides (path,status,badges_json,filters_json,updated_at,updated_by) VALUES (?,?,?,?,?,?) ON CONFLICT(path) DO UPDATE SET status=excluded.status,badges_json=excluded.badges_json,filters_json=excluded.filters_json,updated_at=excluded.updated_at,updated_by=excluded.updated_by').bind(path,status,JSON.stringify(badges),JSON.stringify(filters),now,s.user).run(); await log(env,s,'page_meta.update',path,{status,badges,filters}); return Response.redirect(new URL(adminLink(env,'badges',{edit:path,saved:'1'}),req.url).toString(),303); }
async function saveBadge(req, env){ const auth=session(env,req); if(auth.denied) return auth.denied; const s=auth.session; if(!canAdmin(s)||!db(env)) return json({error:'Forbidden'},403); const p=await formData(req); const key=cleanKey(p.key); if(!key) return json({error:'Invalid badge key'},400); const fr=cleanText(p.label_fr||key,80)||key, en=cleanText(p.label_en||fr,80)||fr, icon=cleanText(p.icon,8), color=cleanColor(p.color), active=p.active==='0'?0:1, now=new Date().toISOString(); await init(env); await db(env).prepare('INSERT INTO badge_definitions (key,label_fr,label_en,icon,color,active,created_at,updated_at,updated_by) VALUES (?,?,?,?,?,?,?,?,?) ON CONFLICT(key) DO UPDATE SET label_fr=excluded.label_fr,label_en=excluded.label_en,icon=excluded.icon,color=excluded.color,active=excluded.active,updated_at=excluded.updated_at,updated_by=excluded.updated_by').bind(key,fr,en,icon,color,active,now,now,s.user).run(); await log(env,s,'badge_definition.upsert',key,{fr,en,icon,color,active}); return Response.redirect(new URL(adminLink(env,'badges',{badgeKey:key,badgeSaved:'1'}),req.url).toString(),303); }
async function moderate(req, env){ const auth=session(env,req); if(auth.denied) return auth.denied; const s=auth.session; if(!canAdmin(s)||!db(env)) return json({error:'Forbidden'},403); const p=await formData(req); await init(env); if(p.action==='purge-archived'){ if(!isOwner(s)) return json({error:'Owner only'},403); const days=[30,60,90,180,365].includes(Number(p.days))?Number(p.days):90; const cutoff=new Date(Date.now()-days*86400000).toISOString(); const r=await db(env).prepare("DELETE FROM article_feedback_comments WHERE hidden=1 AND datetime(COALESCE(handled_at,created_at)) <= datetime(?)").bind(cutoff).run(); await log(env,s,'feedback.purge_archived',`${days}d`,{deleted:r?.meta?.changes||0}); return Response.redirect(new URL(adminLink(env,'feedback',{purged:'1'}),req.url).toString(),303); } const id=Number(p.id||0); if(!id) return json({error:'Invalid id'},400); if(p.action==='delete'){ if(!isOwner(s)) return json({error:'Owner only'},403); await db(env).prepare('DELETE FROM article_feedback_comments WHERE id=?').bind(id).run(); await log(env,s,'feedback.delete',String(id)); return Response.redirect(new URL(adminLink(env,'feedback',{deleted:'1'}),req.url).toString(),303); } const status=['open','read','resolved','archived'].includes(p.status)?p.status:'read'; const hidden=status==='archived'?1:0; const now=new Date().toISOString(); await db(env).prepare('UPDATE article_feedback_comments SET moderation_status=?,hidden=?,handled_by=?,handled_at=? WHERE id=?').bind(status,hidden,s.user,now,id).run(); await log(env,s,'feedback.moderate',String(id),{status,hidden}); return Response.redirect(new URL(adminLink(env,'feedback',{moderated:'1'}),req.url).toString(),303); }
async function saveReview(d,path,s,days){ const [feedbackRow,commentRow]=await Promise.all([d.prepare('SELECT COALESCE(SUM(no_count),0) AS noCount FROM article_feedback WHERE path=?').bind(path).first(),d.prepare("SELECT COALESCE(MAX(id),0) AS commentId FROM article_feedback_comments WHERE path=? AND hidden=0 AND moderation_status IN ('open','read')").bind(path).first()]); const baselineNo=Number(feedbackRow?.noCount||0), baselineCommentId=Number(commentRow?.commentId||0), now=new Date().toISOString(), until=new Date(Date.now()+days*86400000).toISOString(); await d.prepare('INSERT INTO page_review_snoozes (path,snoozed_until,reviewed_at,reviewed_by,baseline_no_count,baseline_comment_id,updated_at) VALUES (?,?,?,?,?,?,?) ON CONFLICT(path) DO UPDATE SET snoozed_until=excluded.snoozed_until,reviewed_at=excluded.reviewed_at,reviewed_by=excluded.reviewed_by,baseline_no_count=excluded.baseline_no_count,baseline_comment_id=excluded.baseline_comment_id,updated_at=excluded.updated_at').bind(path,until,now,s.user,baselineNo,baselineCommentId,now).run(); return {until,baselineNo,baselineCommentId}; }
function bulkPreviewHtml(req,env,s,paths,days,pages){ return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Confirm bulk review</title><style>body{margin:0;background:#0d0d0f;color:#f5f7fb;font:14px/1.5 Inter,system-ui,sans-serif}.box{max-width:900px;margin:40px auto;padding:24px;border:1px solid #303039;border-radius:18px;background:#17171b}code{background:#25252d;padding:2px 6px;border-radius:7px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:20px}.button{border:1px solid #303039;border-radius:10px;color:#fff;background:#222;padding:9px 13px;text-decoration:none;font-weight:800;cursor:pointer}.primary{background:#173b70;border-color:#4c91ff}li{margin:8px 0}</style></head><body><main class="box"><h1>Confirm bulk review</h1><p>You are about to mark <strong>${n(paths.length)} pages</strong> as OK for <strong>${n(days)} days</strong>. This does not modify their public status or badges.</p><ul>${paths.map(p=>`<li><strong>${h(pageInfo(p,pages).title)}</strong> <code>${h(p)}</code></li>`).join('')}</ul><form method="post" action="${h(adminAction(env,'review'))}"><input type="hidden" name="action" value="bulk-confirm"><input type="hidden" name="days" value="${h(days)}">${paths.map(p=>`<input type="hidden" name="path" value="${h(p)}">`).join('')}<div class="actions"><button class="button primary" type="submit">Confirm ${n(paths.length)} pages</button><a class="button" href="${h(adminLink(env,'to-review',{reviewView:'attention'}))}">Cancel</a></div></form></main></body></html>`; }
async function reviewDecision(req,env){ const auth=session(env,req); if(auth.denied) return auth.denied; const s=auth.session; if(!canAdmin(s)||!db(env)) return json({error:'Forbidden'},403); if(req.method!=='POST') return json({error:'Method'},405); const p=await formData(req); const rawPaths=unique([].concat(p.path||[]).map(cleanPath).filter(x=>x!=='/')); if(!rawPaths.length) return Response.redirect(new URL(adminLink(env,'to-review',{reviewView:'attention',none:'1'}),req.url).toString(),303); const d=db(env); await init(env); if(p.action==='cancel'){ await d.prepare('DELETE FROM page_review_snoozes WHERE path=?').bind(rawPaths[0]).run(); await log(env,s,'page_review.review_now',rawPaths[0]); return Response.redirect(new URL(adminLink(env,'to-review',{reviewView:'scheduled',reviewNow:'1'}),req.url).toString(),303); } const pageIndex=await assetJson(req,env,'/page-updates.json')||[]; const pages=Array.isArray(pageIndex)?pageIndex:[]; const allowedPaths=new Set(pages.map(x=>cleanPath(x.path))); const paths=rawPaths.filter(x=>allowedPaths.has(x)); if(!paths.length) return json({error:'No valid current page selected'},400); const requested=Number(p.days||60); const days=[30,60,90].includes(requested)?requested:60; if(p.action==='bulk-preview') return new Response(bulkPreviewHtml(req,env,s,paths,days,pages),{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex,nofollow'}}); if(p.action==='bulk-confirm'){ for(const path of paths) await saveReview(d,path,s,days); await log(env,s,'page_review.bulk_ok_for_now','bulk',{days,count:paths.length}); return Response.redirect(new URL(adminLink(env,'to-review',{reviewView:'scheduled',reviewed:String(days),count:String(paths.length)}),req.url).toString(),303); } const result=await saveReview(d,paths[0],s,days); await log(env,s,'page_review.ok_for_now',paths[0],{days,...result}); return Response.redirect(new URL(adminLink(env,'to-review',{reviewView:'scheduled',reviewed:String(days)}),req.url).toString(),303); }
async function recordFeedback(req, env){ if(req.method!=='POST') return json({error:'Method'},405); let p; try{p=await req.json()}catch{return json({error:'JSON'},400)}; const vote=p.vote==='yes'?'yes':p.vote==='no'?'no':''; if(!vote) return json({error:'vote'},400); const d=db(env); if(!d) return json({ok:true,stored:false}); await init(env); const path=cleanPath(p.path), lang=p.language==='fr'?'fr':'en', now=new Date().toISOString(), yes=vote==='yes'?1:0, no=vote==='no'?1:0, reason=vote==='no'&&FEEDBACK_REASONS.includes(p.reason)?p.reason:''; await d.prepare('INSERT INTO article_feedback (path,language,yes_count,no_count,created_at,updated_at) VALUES (?,?,?,?,?,?) ON CONFLICT(path,language) DO UPDATE SET yes_count=yes_count+?,no_count=no_count+?,updated_at=excluded.updated_at').bind(path,lang,yes,no,now,now,yes,no).run(); const comment=vote==='no'?cleanText(p.comment):''; if(vote==='no'&&(comment||reason)) await d.prepare('INSERT INTO article_feedback_comments (path,language,comment,reason,created_at) VALUES (?,?,?,?,?)').bind(path,lang,comment,reason,now).run(); await bumpAnalytics(d,vote==='yes'?'feedback_yes':'feedback_no',path,reason,lang,now); return json({ok:true,stored:true,commentStored:Boolean(comment),reasonStored:Boolean(reason)}); }
async function recordAnalytics(req, env){ if(req.method!=='POST') return json({error:'Method'},405); let p; try{p=await req.json()}catch{return json({error:'JSON'},400)}; if(!['pageview','not_found','search_zero','outbound'].includes(p.event)) return json({error:'event'},400); const detail=['','installation','server','pokemon','gameplay','performance','support','version','other','curseforge','discord','github','bisecthosting','gitbook','external'].includes(p.detail)?p.detail:''; const d=db(env); if(d){ await init(env); await bumpAnalytics(d,p.event,cleanPath(p.path),detail,p.language==='fr'?'fr':'en'); } return new Response(null,{status:204}); }
async function recordZeroTerm(req,env){ if(req.method!=='POST')return json({error:'Method'},405); let p; try{p=await req.json()}catch{return json({error:'JSON'},400)}; const query=cleanText(p.query,120).toLowerCase(); if(query.length<2)return new Response(null,{status:204}); const d=db(env); if(!d)return new Response(null,{status:204}); await init(env); const category=FILTERS.includes(p.category)?p.category:['installation','pokemon','performance','support','version','other'].includes(p.category)?p.category:'other', lang=p.language==='fr'?'fr':'en', now=new Date().toISOString(), bucket=hourBucket(now); await d.prepare('INSERT INTO search_zero_terms (query,category,language,bucket,count,created_at,updated_at) VALUES (?,?,?,?,1,?,?) ON CONFLICT(query,category,language,bucket) DO UPDATE SET count=count+1,updated_at=excluded.updated_at').bind(query,category,lang,bucket,now,now).run().catch(()=>null); return new Response(null,{status:204}); }
async function recordSearchQueryEvent(req,env){ if(req.method!=='POST')return json({error:'Method'},405); let p; try{p=await req.json()}catch{return json({error:'JSON'},400)}; const query=cleanText(p.query,120).toLowerCase(); if(query.length<2||!['search','click','zero'].includes(p.event))return new Response(null,{status:204}); const d=db(env); if(!d)return new Response(null,{status:204}); await init(env); const category=FILTERS.includes(p.category)?p.category:['installation','pokemon','performance','support','version','other'].includes(p.category)?p.category:'other', lang=p.language==='fr'?'fr':'en', now=new Date().toISOString(), bucket=hourBucket(now); await d.prepare('INSERT INTO search_query_events (query,event,category,language,bucket,count,created_at,updated_at) VALUES (?,?,?,?,?,1,?,?) ON CONFLICT(query,event,category,language,bucket) DO UPDATE SET count=count+1,updated_at=excluded.updated_at').bind(query,p.event,category,lang,bucket,now,now).run().catch(()=>null); return new Response(null,{status:204}); }

async function admin(req, env){ const auth=session(env,req); if(auth.denied) return auth.denied; const s=auth.session; const pl=await payload(req,env); return new Response(html(req,env,s,pl),{headers:{'content-type':'text/html; charset=utf-8','cache-control':'no-store','x-robots-tag':'noindex,nofollow'}}); }
function html(req, env, s, pl){ const url=new URL(req.url); const tabs=['overview','pages','to-review','stats','feedback','badges','audit','logs','maintenance']; if(isOwner(s)) tabs.push('security'); const tab=tabs.includes(url.searchParams.get('tab'))?url.searchParams.get('tab'):'overview'; const pages=pl.pageUpdates, meta=pl.pageMeta, base=pl.pageMetaBase, st=pl.stats, audit=pl.audit||{}, fb=st.feedback||[], comments=st.comments||[], active=(url.searchParams.get('path')?comments.filter(c=>c.path===url.searchParams.get('path')):comments).filter(c=>!c.hidden), archived=(url.searchParams.get('path')?comments.filter(c=>c.path===url.searchParams.get('path')):comments).filter(c=>c.hidden), badges=st.badges||[], logs=st.logs||[], reviewSnoozes=st.reviewSnoozes||[], queue=reviewQueue(pages,meta,fb,comments,st.reviewAnalytics||[],reviewSnoozes), snoozed=currentSnoozes(reviewSnoozes,fb,comments,pages), recentReviews=reviewedRecently(reviewSnoozes,pages); const yes=fb.reduce((a,x)=>a+Number(x.yes||0),0), no=fb.reduce((a,x)=>a+Number(x.no||0),0); const pageFilter=filterPages(pages,meta,fb,comments,url.searchParams), sliced=pageSlice(pageFilter.list,url.searchParams); const badgeKeys=[...new Set([...Object.keys(base.labels?.fr?.badges||base.labels?.en?.badges||{}),...badges.filter(b=>b.active).map(b=>b.key)])].sort(); const selectedPath=pages.some(p=>p.path===url.searchParams.get('edit'))?url.searchParams.get('edit'):(pages.find(p=>p.path!=='/')?.path||'/'); const selectedMeta=pageMetaFor(meta,selectedPath); const selectedBadgeKey=cleanKey(url.searchParams.get('badgeKey')||''); const selectedBadge=badges.find(b=>b.key===selectedBadgeKey)||{key:selectedBadgeKey,labelFr:'',labelEn:'',icon:'',color:'',active:1}; const pageOptions=pages.map(p=>select(p.path,`${p.title||p.path} • ${p.path}`,selectedPath)).join(''); const badgeOptions=['',...badges.map(b=>b.key)].map(k=>select(k,k?`${k} • ${badges.find(b=>b.key===k)?.labelFr||k}`:'New badge',selectedBadgeKey)).join(''); const q=url.searchParams; const critical=queue.filter(x=>x.severity==='Critical').length, high=queue.filter(x=>x.severity==='High').length, overviewQueue=queue.filter(x=>x.severity==='Critical'||x.severity==='High'), health=wikiHealth(audit,queue,comments); const reviewView=['attention','scheduled','recent'].includes(q.get('reviewView'))?q.get('reviewView'):'attention'; const auditView=['overview','links','translations','content','sources'].includes(q.get('auditView'))?q.get('auditView'):'overview'; const logView=['global','badges','reviews','feedback','system'].includes(q.get('logView'))?q.get('logView'):'global';
 const reviewNav=subnav(env,'to-review','reviewView',reviewView,[['attention','Needs attention'],['scheduled','Scheduled'],['recent','Recently reviewed']]);
 const reviewBody=reviewView==='scheduled'?`${reviewCalendar(snoozed)}${q.get('reviewed')?`<p class="notice">Review acknowledgement saved for ${h(q.get('reviewed'))} days${q.get('count')?` on ${h(q.get('count'))} pages`:''}.</p>`:''}${q.get('reviewNow')?'<p class="notice">Scheduled review cancelled.</p>':''}<section class="section"><h2>OK for now</h2>${snoozedReviewTable(snoozed,env)}</section>`:reviewView==='recent'?`<section class="section"><div class="section-head"><h2>Recently reviewed</h2>${badge(`${n(recentReviews.length)} in 90 days`)}</div>${recentReviewTable(recentReviews,env)}</section>`:`${q.get('none')?'<p class="notice warn-note">Select at least one page before previewing a bulk review.</p>':''}<div class="hero-grid">${card('Needs attention',queue.length,'all suggestions')}${card('Critical',critical,'score 80+')}${card('High',high,'score 60–79')}${card('OK for now',snoozed.length,'scheduled')}</div><p class="data-note">Medium and Low are maintenance suggestions, not proof that content is wrong. Use the 30 / 60 / 90 day acknowledgement after checking a page. Bulk actions always show a confirmation preview first.</p><section class="section"><h2>Pages needing attention</h2>${bulkReviewTable(queue,env)}</section>`;
 const auditNav=subnav(env,'audit','auditView',auditView,[['overview','Overview'],['links','Links'],['translations','Translations'],['content','Content'],['sources','Sources & Metadata']]);
 const auditBody=auditView==='links'?auditLinks(audit,pages):auditView==='translations'?auditTranslations(audit,pages):auditView==='content'?auditContent(audit,pages):auditView==='sources'?auditSources(audit):auditOverview(audit);
 const panels={
 overview:`<div class="hero-grid">${card('Wiki Health',`${health.score}%`,health.label)}${card('Pages',pages.length,`FR ${pages.filter(p=>p.language==='fr').length} / EN ${pages.filter(p=>p.language==='en').length}`)}${card('Needs attention',overviewQueue.length,`${critical} critical • ${high} high`)}${card('Next reviews',snoozed.filter(x=>Date.parse(x.snoozedUntil)<=Date.now()+30*86400000).length,'within 30 days')}</div><div class="grid-2"><section class="section"><div class="section-head"><h2>Pages needing attention</h2>${badge(`${n(overviewQueue.length)} critical / high`,overviewQueue.length?'warn':'ok')}</div>${reviewTable(overviewQueue.slice(0,12),env)}</section><section class="section"><h2>Health breakdown</h2><ul class="check-list"><li>${n(audit?.counts?.critical||0)} critical build audit issues</li><li>${n(audit?.counts?.warning||0)} build audit warnings</li><li>${n(critical)} critical review items</li><li>${n(high)} high review items</li><li>${n(health.open)} active feedback items</li></ul><a class="button" href="${h(adminLink(env,'audit'))}">Open Audit</a></section></div>`,
 pages:`<section class="section"><div class="section-head"><h2>Pages</h2>${badge(`${n(sliced.total)} visible / ${n(pages.length)} total`)}</div><form class="filter-form" method="get" action="${h(adminBase(env))}"><input type="hidden" name="tab" value="pages"><input name="q" value="${h(pageFilter.filters.search)}" placeholder="Search title, path, badge, filter"><select name="status"><option value="all">All statuses</option>${STATUSES.map(x=>select(x,x,pageFilter.filters.status)).join('')}</select><select name="badge"><option value="all">All badges</option>${badgeKeys.map(x=>select(x,x,pageFilter.filters.b)).join('')}</select><select name="feedback">${[['all','All feedback'],['negative','Negative feedback'],['open','Open comments']].map(x=>select(x[0],x[1],pageFilter.filters.mode)).join('')}</select><input type="hidden" name="lang" value="${h(pageFilter.filters.lang)}"><button class="button primary">Apply</button><a class="button" href="${h(adminLink(env,'pages'))}">Reset</a></form><div class="toolbar"><span class="muted">Language</span>${['all','fr','en'].map(l=>`<a class="button mini ${pageFilter.filters.lang===l?'is-current':''}" href="${h(adminLink(env,'pages',{...Object.fromEntries(q),lang:l,p:'1'}))}">${l.toUpperCase()}</a>`).join('')}</div><div class="page-list">${pageCards(sliced.visible,meta,env)}</div>${pageControls(env,q,sliced)}</section>`,
 'to-review':`${reviewNav}${reviewBody}`,
 feedback:`<div class="hero-grid">${card('Helpful votes',yes,'yes')}${card('Needs work',no,'no')}${card('Active comments',active.length,'visible')}${card('Archived comments',archived.length,'hidden')}</div>${q.get('moderated')?'<p class="notice">Feedback moderation updated.</p>':''}${q.get('deleted')?'<p class="notice">Feedback comment permanently deleted.</p>':''}${q.get('purged')?'<p class="notice">Old archived feedback comments purged.</p>':''}<section class="section"><div class="section-head"><h2>Article feedback</h2>${badge(`${fb.length} pages`,no?'warn':'info')}</div>${feedbackTable(fb,comments,env,pages)}</section><section class="section"><div class="section-head"><h2>Active feedback comments</h2>${badge(`${active.length} active`,active.length?'warn':'ok')}</div>${commentsTable(active,env,s,false,pages)}</section><section class="section"><div class="section-head"><h2>Archived comments</h2>${badge(`${archived.length} archived`)}</div>${commentsTable(archived,env,s,true,pages)}</section>${isOwner(s)?`<section class="section"><h2>Archived cleanup</h2><form class="inline-form" method="post" action="${h(adminAction(env,'feedback'))}"><input type="hidden" name="action" value="purge-archived"><select name="days"><option value="30">Older than 30 days</option><option value="60">Older than 60 days</option><option selected value="90">Older than 90 days</option><option value="180">Older than 180 days</option><option value="365">Older than 365 days</option></select><button class="button danger">Purge archived</button></form></section>`:''}`,
 badges:`<div class="grid-2"><section class="section"><h2>Edit page options</h2>${q.get('saved')?'<p class="notice">Saved.</p>':''}<form class="form-grid" method="get" action="${h(adminBase(env))}"><input type="hidden" name="tab" value="badges"><label>Choose page<select name="edit">${pageOptions}</select></label><button class="button">Load page</button></form><hr><form class="form-grid" method="post" action="${h(adminAction(env,'page-meta'))}"><input type="hidden" name="path" value="${h(selectedPath)}"><p class="muted">Editing <code>${h(selectedPath)}</code></p><label>Status<select name="status">${STATUSES.map(x=>select(x,x,selectedMeta.status)).join('')}</select></label><strong>Badges</strong><div class="checks">${badgeKeys.map(x=>check('badges',x,(selectedMeta.badges||[]).includes(x))).join('')}</div><strong>Filters</strong><div class="checks">${FILTERS.map(x=>check('filters',x,(selectedMeta.filters||[]).includes(x))).join('')}</div><button class="button primary">Save page override</button></form></section><section class="section"><h2>Create or update badge</h2>${q.get('badgeSaved')?'<p class="notice">Badge saved.</p>':''}<form class="form-grid" method="get" action="${h(adminBase(env))}"><input type="hidden" name="tab" value="badges"><label>Edit existing badge<select name="badgeKey">${badgeOptions}</select></label><button class="button">Load badge</button></form><hr><form class="form-grid" method="post" action="${h(adminAction(env,'badge'))}"><label>Badge key<input name="key" required value="${h(selectedBadge.key||'')}"></label><label>Label FR<input name="label_fr" value="${h(selectedBadge.labelFr||'')}"></label><label>Label EN<input name="label_en" value="${h(selectedBadge.labelEn||'')}"></label><label>Icon<input name="icon" value="${h(selectedBadge.icon||'')}"></label><label>Color<input name="color" value="${h(selectedBadge.color||'')}"></label><label>Status<select name="active">${select('1','Active',String(selectedBadge.active??1))}${select('0','Disabled',String(selectedBadge.active??1))}</select></label><button class="button primary">Save badge definition</button></form></section></div><section class="section"><h2>Dynamic badges</h2>${rows(badges,[['Key',i=>`<code>${h(i.key)}</code>`],['Labels',i=>`FR: ${h(i.labelFr)}<br>EN: ${h(i.labelEn)}`],['Usage',i=>n(usage(pages,meta).get(i.key)||0)],['Status',i=>badge(i.active?'active':'disabled',i.active?'ok':'warn')],['Action',i=>`<a class="button mini" href="${h(adminLink(env,'badges',{badgeKey:i.key}))}">Edit</a>`]],'No dynamic badge.')}</section>`,
 stats:statsPanel(env,st,pages,meta,fb,comments),
 audit:`${auditNav}${auditBody}`,
 logs:`${logsPanel(logs,env,logView)}`,
 security:`<section class="section"><h2>Owner-only Security</h2><ul class="check-list"><li>Protect the hidden admin routes with Cloudflare Access.</li><li>Protect admin API mutations with the same Access policy.</li><li>Keep authorized accounts restricted to the intended maintainers.</li><li>Keep Basic Auth as a second lock.</li></ul></section>`,
 maintenance:`<section class="section"><h2>Maintenance</h2><ul class="check-list"><li>D1 stores feedback, analytics, stable search conversion, review acknowledgements, overrides, badge definitions and meaningful admin logs.</li><li>Admin page views are no longer logged.</li><li>Markdown pages remain on GitHub.</li><li>Audit V2 is generated at build time in wiki-audit.json.</li><li>Review acknowledgements do not modify public badges or page status.</li></ul></section>` };
 const title=tab==='to-review'?'To Review':tab[0].toUpperCase()+tab.slice(1); return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>Wiki Admin</title><style>:root{color-scheme:dark;--line:#303039;--line2:#24242b;--text:#f5f7fb;--muted:#a5adbb;--accent:#4c91ff}*{box-sizing:border-box}body{margin:0;background:#0d0d0f;color:var(--text);font:14px/1.5 Inter,system-ui,sans-serif}.admin-shell{display:grid;grid-template-columns:280px 1fr;min-height:100vh}.admin-sidebar{padding:22px 18px;border-right:1px solid var(--line);background:#111114}.admin-brand{display:flex;gap:12px;align-items:center;margin-bottom:20px}.admin-logo{display:grid;place-items:center;width:42px;height:42px;border-radius:14px;background:#1c2535}.admin-nav{display:grid;gap:16px}.nav-group{display:grid;gap:6px}.nav-group>small{padding:0 10px;color:#777f8d;font-size:10px;font-weight:900;letter-spacing:.12em;text-transform:uppercase}.admin-nav a,.button{border:1px solid var(--line);border-radius:10px;color:var(--text);background:rgba(255,255,255,.04);text-decoration:none;font-weight:800}.admin-nav a{padding:9px 11px}.admin-nav a.is-active,.button.primary,.button.is-current,.subnav a.is-active{background:rgba(76,145,255,.18);border-color:rgba(76,145,255,.55)}.button{display:inline-flex;align-items:center;justify-content:center;min-height:36px;height:auto;padding:8px 11px;line-height:1.2;cursor:pointer}.button.mini{min-height:29px;padding:5px 8px;font-size:12px}.button.success{border-color:rgba(32,200,117,.48);background:rgba(32,200,117,.14);color:#83e9b4}.button.danger,.status.danger{border-color:rgba(239,68,68,.45);background:rgba(239,68,68,.13);color:#ff9696}.admin-main{padding:26px min(42px,4vw) 42px}.admin-topbar{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;margin-bottom:20px}.admin-topbar>.admin-actions{align-self:flex-start}.muted{color:var(--muted)}.hero-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:18px 0}.grid-2{display:grid;grid-template-columns:1fr 1fr;gap:16px}.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.card,.section{border:1px solid var(--line);border-radius:18px;background:#17171b;padding:18px}.card strong{display:block;font-size:25px}.section{margin-top:16px;overflow:auto}.section-head{display:flex;justify-content:space-between;gap:14px}.status,.pill,.signal{display:inline-flex;border-radius:999px;font-size:12px;font-weight:850}.status{padding:4px 9px;background:rgba(76,145,255,.12);color:#a8c9ff}.ok{background:rgba(32,200,117,.13);color:#71e0a6}.warn{background:rgba(245,158,11,.14);color:#f8c46a}.pill,.signal{margin:2px 4px 2px 0;padding:3px 8px;border:1px solid #454550}.signal{background:#202027;color:#c7ced9;font-size:11px}table{width:100%;border-collapse:collapse}th,td{padding:10px 9px;border-top:1px solid var(--line2);text-align:left;vertical-align:top}th{font-size:11px;text-transform:uppercase}code{padding:2px 6px;border-radius:7px;background:#25252d;color:#dbeafe}.form-grid,.filter-form{display:grid;gap:14px}.filter-form{grid-template-columns:minmax(220px,1.4fr) repeat(3,minmax(140px,.7fr)) auto auto}.form-grid input,.form-grid select,.filter-form input,.filter-form select,.inline-form select,.bulk-review select{min-height:40px;border:1px solid var(--line);border-radius:12px;background:#111116;color:#fff;padding:8px 11px}.checks,.inline-form,.admin-actions,.toolbar,.pagination{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.review-actions{display:inline-flex}.period-toolbar{margin:0 0 10px}.check{border:1px solid var(--line2);border-radius:999px;padding:7px 10px}.page-list{display:grid;gap:8px;margin-top:14px}.page-card{display:grid;grid-template-columns:1.4fr .8fr .6fr;gap:12px;border:1px solid var(--line2);border-radius:13px;background:rgba(255,255,255,.025);padding:12px}.notice{padding:12px;border:1px solid rgba(32,200,117,.35);border-radius:12px;background:rgba(32,200,117,.1)}.warn-note{border-color:rgba(245,158,11,.35);background:rgba(245,158,11,.1)}.data-note{padding:11px 13px;border:1px solid rgba(76,145,255,.25);border-radius:12px;background:rgba(76,145,255,.07);color:#b7c4d8;font-size:12px}.empty{padding:18px;border:1px dashed #3a3a45;border-radius:14px;color:var(--muted)}.check-list{display:grid;gap:9px;list-style:none;padding:0}.subnav{display:flex;gap:8px;flex-wrap:wrap;margin:0 0 16px}.subnav a{padding:8px 11px;border:1px solid var(--line);border-radius:999px;color:#c8d0dc;text-decoration:none;font-weight:850;background:#15151a}.log-list{display:grid;gap:8px}.log-card{display:grid;grid-template-columns:minmax(250px,1fr) minmax(220px,.8fr);gap:14px;padding:12px 14px;border:1px solid var(--line2);border-radius:13px;background:#151519}.log-card>div:first-child{display:flex;gap:10px;align-items:center}.log-card>div:last-child{display:flex;flex-direction:column;align-items:flex-end;gap:4px;text-align:right}.log-card small{display:block;color:var(--muted)}.log-icon{display:grid;place-items:center;width:32px;height:32px;border-radius:9px;background:#202027}.text-link{color:#8db9ff;text-decoration:none}.bulk-review>.toolbar{margin-bottom:10px}@media(max-width:1100px){.admin-shell{grid-template-columns:1fr}.hero-grid,.grid-2,.grid-3,.filter-form,.page-card,.log-card{grid-template-columns:1fr}.log-card>div:last-child{align-items:flex-start;text-align:left}}</style></head><body><div class="admin-shell"><aside class="admin-sidebar"><div class="admin-brand"><div class="admin-logo">🛠️</div><div><strong>Cobblemon Realms</strong><br><small class="muted">Wiki Admin Console</small></div></div><nav class="admin-nav">${adminNav(env,tab,s)}</nav><p class="muted">Signed in as ${h(s.user)} (${h(s.role)})</p></aside><main class="admin-main"><div class="admin-topbar"><div><h1>${h(title)}</h1><p class="muted">Protected admin console.</p></div><div class="admin-actions"><a class="button" href="/" target="_blank">Open wiki</a><a class="button" href="${h(adminLink(env,tab,{period:st.period,reviewView:tab==='to-review'?reviewView:'',auditView:tab==='audit'?auditView:'',logView:tab==='logs'?logView:''}))}">Refresh</a></div></div>${panels[tab]||panels.overview}</main></div></body></html>`; }

class HeadInjector{ element(e){ e.append('<link rel="stylesheet" href="/assets/discord.css?v=community-badges-4" data-community-badges="true"><link rel="stylesheet" href="/assets/gitbook-blocks.css?v=gitbook-reference-3" data-gitbook-blocks="true"><style id="cr-server-online-color">.server-badge.is-online{border-color:#2e8f5c!important;background:linear-gradient(180deg,rgba(46,143,92,.42),rgba(46,143,92,.24))!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.08),0 0 0 1px rgba(46,143,92,.18),0 0 16px rgba(46,143,92,.16)!important}.server-badge.is-online:hover{border-color:#2e8f5c!important}.server-badge.is-online .server-state i{background:#2e8f5c!important}.server-badge.is-online .server-icon{border-color:#2e8f5c!important}</style>',{html:true}); }}
class BodyInjector{ element(e){ e.append('<script src="/assets/gitbook-blocks.js?v=gitbook-reference-3"></script>',{html:true}); }}

export default { async fetch(req, env, ctx){ const url=new URL(req.url); if(isAdminPath(url,env)) return admin(req,env); if(isActionPath(url,env,'status')){ const a=session(env,req); if(a.denied) return a.denied; return json(await payload(req,env)); } if(isActionPath(url,env,'page-meta')) return saveMeta(req,env); if(isActionPath(url,env,'badge')) return saveBadge(req,env); if(isActionPath(url,env,'feedback')) return moderate(req,env); if(isActionPath(url,env,'review')) return reviewDecision(req,env); if(url.pathname==='/page-meta.json'){ const raw=await assetJson(req,env,'/page-meta.json')||{}; const st=await baseStats(env); return json(applyMeta(raw,st.overrides,st.badges)); } if(url.pathname==='/api/feedback') return recordFeedback(req,env); if(url.pathname==='/api/analytics') return recordAnalytics(req,env); if(url.pathname==='/api/search-zero-term') return recordZeroTerm(req,env); if(url.pathname==='/api/search-query-event') return recordSearchQueryEvent(req,env); if(url.pathname==='/api/discord'){ try{ const r=await fetch(`https://discord.com/api/v10/invites/${INVITE_CODE}?with_counts=true&with_expiration=true`); const d=await r.json(); return json({name:d.guild?.name||'Cobblemon Realms',online:d.approximate_presence_count||0,members:d.approximate_member_count||0,inviteUrl:`https://discord.gg/${INVITE_CODE}`},200,'public, max-age=60'); }catch{return json({error:'Discord unavailable'},502)} } if(url.pathname==='/api/curseforge'){ try{ const r=await fetch(`https://img.shields.io/curseforge/dt/${CURSEFORGE_PROJECT_ID}.json`); const d=await r.json(); return json({downloads:d.message,projectId:Number(CURSEFORGE_PROJECT_ID),projectUrl:'https://www.curseforge.com/minecraft/modpacks/cobblemon-realms'},200,'public, max-age=120'); }catch{return json({error:'CurseForge unavailable'},502)} } if(url.pathname==='/api/server'){ try{ const r=await fetch(`https://api.mcsrvstat.us/3/${encodeURIComponent(MINECRAFT_SERVER_ADDRESS)}`,{signal:AbortSignal.timeout(8000)}); const d=await r.json(); const online=d.online===true; return json({online,players:{online:online&&Number.isFinite(d.players?.online)?d.players.online:0,max:online&&Number.isFinite(d.players?.max)?d.players.max:0},icon:typeof d.icon==='string'?d.icon:null,joinUrl:`https://discord.gg/${INVITE_CODE}`},200,'public, max-age=30'); }catch{return json({error:'Server unavailable'},502)} } const res=await env.ASSETS.fetch(req); const ct=res.headers.get('content-type')||''; return ct.includes('text/html') ? new HTMLRewriter().on('head',new HeadInjector()).on('body',new BodyInjector()).transform(res) : res; } };
